import { Component, computed, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { formatShowDate } from '../date-utils';
import { API_BASE_URL, Movie, Screening } from '../models';
import { Toast } from '../toast';
import { AuditoriumCell, SeatState, buildAuditorium } from './auditorium';

interface LoadedScreening {
  screening: Screening;
  movie: Movie;
}

/** A selected seat (`start === end`) or couch (`end === start + 1`) within one row. */
interface SelectedUnit {
  row: number;
  start: number;
  end: number;
}

/** A `Row <r>: <seats>` line of the selected-seats panel. */
interface SelectedRow {
  row: number;
  seats: string;
}

/** Background state of a cell: its own state, or `selected` while it is part of the selection. */
export type DisplayState = SeatState | 'selected';

const MAX_SEATS = 10;
const LIMIT_MESSAGE = 'Maximum 10 seats per booking';

const LEGEND: readonly { state: DisplayState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

function unitKey(row: number, start: number): string {
  return `${row}:${start}`;
}

/** Number of seats a unit holds: a seat is 1, a couch is 2. */
function seatsIn(unit: SelectedUnit): number {
  return unit.end - unit.start + 1;
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toast = inject(Toast);

  /** Null until the screening and its movie have loaded. */
  protected readonly view = signal<LoadedScreening | null>(null);

  protected readonly showDate = computed(() => {
    const loaded = this.view();
    return loaded ? formatShowDate(loaded.screening.date, loaded.screening.time) : '';
  });

  protected readonly rows = computed(() => {
    const loaded = this.view();
    return loaded ? buildAuditorium(new Set(loaded.screening.occupiedSeats)) : [];
  });

  protected readonly legend = LEGEND;

  protected readonly selection = signal<SelectedUnit[]>([]);

  protected readonly selectedKeys = computed(
    () => new Set(this.selection().map((unit) => unitKey(unit.row, unit.start))),
  );

  protected readonly selectedCount = computed(() =>
    this.selection().reduce((total, unit) => total + seatsIn(unit), 0),
  );

  /** One line per row with a selection, rows ascending, seats ascending by column. */
  protected readonly selectedRows = computed<SelectedRow[]>(() => {
    const units = [...this.selection()].sort((a, b) => a.row - b.row || a.start - b.start);
    const byRow = new Map<number, string[]>();
    for (const unit of units) {
      const label = unit.start === unit.end ? `${unit.start}` : `${unit.start}-${unit.end}`;
      byRow.set(unit.row, [...(byRow.get(unit.row) ?? []), label]);
    }
    return [...byRow].map(([row, labels]) => ({ row, seats: labels.join(', ') }));
  });

  constructor() {
    this.route.paramMap
      .pipe(
        map((params) => params.get('id') ?? ''),
        switchMap((id) => this.loadScreening(id)),
        takeUntilDestroyed(),
      )
      .subscribe((loaded) => {
        this.view.set(loaded);
        this.selection.set([]);
      });
  }

  protected displayState(row: number, cell: AuditoriumCell): DisplayState | null {
    if (cell.state === null || cell.state === 'unavailable') {
      return cell.state;
    }
    return this.selectedKeys().has(unitKey(row, cell.start)) ? 'selected' : cell.state;
  }

  /** Selects a free seat or couch, or deselects it when already selected. */
  protected toggle(row: number, cell: AuditoriumCell): void {
    if (cell.state === null || cell.state === 'unavailable') {
      return;
    }
    const key = unitKey(row, cell.start);
    if (this.selectedKeys().has(key)) {
      this.selection.update((units) => units.filter((unit) => unitKey(unit.row, unit.start) !== key));
      return;
    }
    const unit: SelectedUnit = { row, start: cell.start, end: cell.end };
    if (this.selectedCount() + seatsIn(unit) > MAX_SEATS) {
      this.toast.show(LIMIT_MESSAGE);
      return;
    }
    this.selection.update((units) => [...units, unit]);
  }

  /** Loads the screening and its movie; any failure redirects to the movie list. */
  private loadScreening(id: string) {
    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${id}`).pipe(
      switchMap((screening) =>
        this.http
          .get<Movie>(`${API_BASE_URL}/movies/${screening.movieId}`)
          .pipe(map((movie) => ({ screening, movie }))),
      ),
      catchError(() => {
        this.router.navigate(['/']);
        return EMPTY;
      }),
    );
  }
}

===== movie-list/movie-list.ts
import { Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { forkJoin, map } from 'rxjs';
import { addDays, englishWeekday, parseIsoDate, startOfDay, toIsoDate } from '../date-utils';
import { API_BASE_URL, Movie, Screening } from '../models';

interface DayOption {
  iso: string;
  label: string;
}

interface MovieCard {
  movie: Movie;
  screenings: Screening[];
}

type LoadState =
  | { status: 'loading' }
  | { status: 'error' }
  | { status: 'loaded'; movies: Movie[]; screenings: Screening[] };

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
  templateUrl: './movie-list.html',
  styleUrl: './movie-list.scss',
})
export class MovieList {
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly today = startOfDay(new Date());
  protected readonly todayIso = toIsoDate(this.today);
  protected readonly todayDate = this.today;

  /** Today and the next four days; the first is labelled `Today`. */
  protected readonly days: DayOption[] = Array.from({ length: 5 }, (_, offset) => {
    const date = addDays(this.today, offset);
    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : englishWeekday(date) };
  });

  private readonly queryDate = toSignal(
    this.route.queryParamMap.pipe(map((params) => params.get('date'))),
    { initialValue: null },
  );

  /** The selected day; a missing, invalid or past `date` selects today. */
  protected readonly selectedIso = computed(() => {
    const requested = this.queryDate();
    if (requested && parseIsoDate(requested) && requested >= this.todayIso) {
      return requested;
    }
    return this.todayIso;
  });

  /** The day chosen in the datepicker, shown only when it is not one of the five day buttons. */
  protected readonly pickedDate = computed(() => {
    const iso = this.selectedIso();
    return this.days.some((day) => day.iso === iso) ? null : parseIsoDate(iso);
  });

  protected readonly state = signal<LoadState>({ status: 'loading' });

  /** Movies with at least one screening on the selected day, in backend order. */
  protected readonly cards = computed<MovieCard[]>(() => {
    const state = this.state();
    if (state.status !== 'loaded') {
      return [];
    }
    const date = this.selectedIso();
    const onDay = state.screenings.filter((screening) => screening.date === date);
    return state.movies.flatMap((movie) => {
      const screenings = onDay
        .filter((screening) => screening.movieId === movie.id)
        .sort((a, b) => a.time.localeCompare(b.time));
      return screenings.length > 0 ? [{ movie, screenings }] : [];
    });
  });

  constructor() {
    this.load();
  }

  protected load(): void {
    this.state.set({ status: 'loading' });
    forkJoin({
      movies: this.http.get<Movie[]>(`${API_BASE_URL}/movies`),
      screenings: this.http.get<Screening[]>(`${API_BASE_URL}/screenings`),
    }).subscribe({
      next: (data) => this.state.set({ status: 'loaded', ...data }),
      error: () => this.state.set({ status: 'error' }),
    });
  }

  protected selectDay(iso: string): void {
    this.router.navigate(['/'], { queryParams: { date: iso } });
  }

  protected onDatePicked(date: Date | null): void {
    if (date) {
      this.selectDay(toIsoDate(date));
    }
  }

  protected openSeats(screeningId: number): void {
    this.router.navigate(['/screenings', screeningId, 'seats']);
  }
}
