import { Injectable } from '@angular/core';

/** A seat (`start === end`) or a couch (`end === start + 1`) within one row. */
export interface SelectedUnit {
  row: number;
  start: number;
  end: number;
}

/** The booking in progress (section 3.1), kept in sessionStorage. */
export interface Booking {
  screeningId: number;
  units: SelectedUnit[];
}

const STORAGE_KEY = 'cinescope.booking';

export function unitKey(row: number, start: number): string {
  return `${row}:${start}`;
}

/** Orders units by row, then by column. */
export function sortUnits(units: readonly SelectedUnit[]): SelectedUnit[] {
  return [...units].sort((a, b) => a.row - b.row || a.start - b.start);
}

/** `Couch <a>-<b>` for a couch, the column number for a single seat (AC-37). */
export function describeSeat(unit: SelectedUnit): string {
  return unit.start === unit.end ? `${unit.start}` : `Couch ${unit.start}-${unit.end}`;
}

/** Reads and writes the booking in sessionStorage, so it survives a reload. */
@Injectable({ providedIn: 'root' })
export class BookingStore {
  read(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return null;
    }
    try {
      const booking = JSON.parse(raw) as Booking;
      return typeof booking?.screeningId === 'number' && Array.isArray(booking.units) ? booking : null;
    } catch {
      return null;
    }
  }

  write(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }

  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
  }
}

import { SelectedUnit } from './booking';

/** Section 5.4: price of one seat by row, and of one couch (two seats). */
const COUCH_PRICE = 89;

/** Price in PLN of one selected seat or couch. */
export function priceOf(unit: SelectedUnit): number {
  if (unit.start !== unit.end) {
    return COUCH_PRICE;
  }
  if (unit.row <= 5) {
    return 25;
  }
  if (unit.row <= 10) {
    return 32;
  }
  return 39;
}

/** Two decimals and the `PLN` suffix, e.g. `25.00 PLN`. */
export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map, switchMap } from 'rxjs';
import { API_BASE_URL, Movie, Screening } from './models';

export interface LoadedScreening {
  screening: Screening;
  movie: Movie;
}

/** Loads a screening together with its movie. Errors are passed on to the caller. */
@Injectable({ providedIn: 'root' })
export class ScreeningLoader {
  private readonly http = inject(HttpClient);

  load(id: string): Observable<LoadedScreening> {
    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${id}`).pipe(
      switchMap((screening) =>
        this.http
          .get<Movie>(`${API_BASE_URL}/movies/${screening.movieId}`)
          .pipe(map((movie) => ({ screening, movie }))),
      ),
    );
  }
}

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { BookingStore } from './booking';

/**
 * Lets a route for screening `:id` open only while the booking holds seats for that screening
 * (section 3.1). Otherwise redirects to the movie list. Runs on every entry, including reloads.
 */
export const bookingGuard: CanActivateFn = (route) => {
  const booking = inject(BookingStore).read();
  const screeningId = Number(route.paramMap.get('id'));
  const allowed = booking !== null && booking.screeningId === screeningId && booking.units.length > 0;
  return allowed ? true : inject(Router).createUrlTree(['/']);
};

import { Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { BookingStore, SelectedUnit, unitKey } from '../booking';
import { formatShowDate } from '../date-utils';
import { LoadedScreening, ScreeningLoader } from '../screening-loader';
import { Toast } from '../toast';
import { AuditoriumCell, SeatState, buildAuditorium } from './auditorium';

/** A `Row <r>: <seats>` line of the selected-seats panel. */
interface SelectedRow {
  row: number;
  seats: string;
}

/** Background state of a cell: its own state, or `selected` while it is part of the selection. */
export type DisplayState = SeatState | 'selected';

const MAX_SEATS = 10;
const LIMIT_MESSAGE = 'Maximum 10 seats per booking';

const LEGEND: readonly { state: DisplayState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

/** Number of seats a unit holds: a seat is 1, a couch is 2. */
function seatsIn(unit: SelectedUnit): number {
  return unit.end - unit.start + 1;
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toast = inject(Toast);
  private readonly booking = inject(BookingStore);
  private readonly screenings = inject(ScreeningLoader);

  /** Null until the screening and its movie have loaded. */
  protected readonly view = signal<LoadedScreening | null>(null);

  protected readonly showDate = computed(() => {
    const loaded = this.view();
    return loaded ? formatShowDate(loaded.screening.date, loaded.screening.time) : '';
  });

  protected readonly rows = computed(() => {
    const loaded = this.view();
    return loaded ? buildAuditorium(new Set(loaded.screening.occupiedSeats)) : [];
  });

  protected readonly legend = LEGEND;

  protected readonly selection = signal<SelectedUnit[]>([]);

  protected readonly selectedKeys = computed(
    () => new Set(this.selection().map((unit) => unitKey(unit.row, unit.start))),
  );

  protected readonly selectedCount = computed(() =>
    this.selection().reduce((total, unit) => total + seatsIn(unit), 0),
  );

  /** One line per row with a selection, rows ascending, seats ascending by column. */
  protected readonly selectedRows = computed<SelectedRow[]>(() => {
    const units = [...this.selection()].sort((a, b) => a.row - b.row || a.start - b.start);
    const byRow = new Map<number, string[]>();
    for (const unit of units) {
      const label = unit.start === unit.end ? `${unit.start}` : `${unit.start}-${unit.end}`;
      byRow.set(unit.row, [...(byRow.get(unit.row) ?? []), label]);
    }
    return [...byRow].map(([row, labels]) => ({ row, seats: labels.join(', ') }));
  });

  constructor() {
    this.route.paramMap
      .pipe(
        map((params) => params.get('id') ?? ''),
        switchMap((id) =>
          this.screenings.load(id).pipe(
            catchError(() => {
              this.router.navigate(['/']);
              return EMPTY;
            }),
          ),
        ),
        takeUntilDestroyed(),
      )
      .subscribe((loaded) => {
        this.view.set(loaded);
        // Keep the booking in progress when it belongs to this screening; otherwise start a new one.
        const existing = this.booking.read();
        const units = existing?.screeningId === loaded.screening.id ? existing.units : [];
        this.commit(units);
      });
  }

  protected displayState(row: number, cell: AuditoriumCell): DisplayState | null {
    if (cell.state === null || cell.state === 'unavailable') {
      return cell.state;
    }
    return this.selectedKeys().has(unitKey(row, cell.start)) ? 'selected' : cell.state;
  }

  /** Selects a free seat or couch, or deselects it when already selected. */
  protected toggle(row: number, cell: AuditoriumCell): void {
    if (cell.state === null || cell.state === 'unavailable') {
      return;
    }
    const key = unitKey(row, cell.start);
    if (this.selectedKeys().has(key)) {
      this.commit(this.selection().filter((unit) => unitKey(unit.row, unit.start) !== key));
      return;
    }
    const unit: SelectedUnit = { row, start: cell.start, end: cell.end };
    if (this.selectedCount() + seatsIn(unit) > MAX_SEATS) {
      this.toast.show(LIMIT_MESSAGE);
      return;
    }
    this.commit([...this.selection(), unit]);
  }

  /** Clears the booking and leaves for the movie list. */
  protected cancel(): void {
    this.booking.clear();
    this.selection.set([]);
    this.router.navigate(['/']);
  }

  /** Opens the summary; does nothing without a selected seat. */
  protected proceed(): void {
    const loaded = this.view();
    if (!loaded || this.selectedCount() === 0) {
      return;
    }
    this.router.navigate(['/screenings', loaded.screening.id, 'summary']);
  }

  /** Sets the selection and stores it as the booking in progress. */
  private commit(units: SelectedUnit[]): void {
    const loaded = this.view();
    this.selection.set(units);
    if (loaded) {
      this.booking.write({ screeningId: loaded.screening.id, units });
    }
  }
}

import { Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { BookingStore, SelectedUnit, describeSeat, sortUnits, unitKey } from '../booking';
import { formatPrice, priceOf } from '../pricing';
import { LoadedScreening, ScreeningLoader } from '../screening-loader';

/** One summary item: a seat or a couch of the booking, with its details. */
interface SummaryItem {
  key: string;
  unit: SelectedUnit;
  movieTitle: string;
  dateTime: string;
  row: number;
  seat: string;
  price: string;
}

/** `Your tickets` (section 6): the booking's seats and couches, with the total and the way on. */
@Component({
  selector: 'app-summary',
  imports: [MatButtonModule],
  templateUrl: './summary.html',
  styleUrl: './summary.scss',
})
export class Summary {
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly booking = inject(BookingStore);
  private readonly screenings = inject(ScreeningLoader);

  /** Null until the screening and its movie have loaded. */
  protected readonly view = signal<LoadedScreening | null>(null);

  /** Seats and couches of the booking in progress; changed by `Remove`. */
  protected readonly units = signal<SelectedUnit[]>(this.booking.read()?.units ?? []);

  protected readonly items = computed<SummaryItem[]>(() => {
    const loaded = this.view();
    if (!loaded) {
      return [];
    }
    return sortUnits(this.units()).map((unit) => ({
      key: unitKey(unit.row, unit.start),
      unit,
      movieTitle: loaded.movie.title,
      dateTime: `${loaded.screening.date} ${loaded.screening.time}`,
      row: unit.row,
      seat: describeSeat(unit),
      price: formatPrice(priceOf(unit)),
    }));
  });

  protected readonly totalLabel = computed(() =>
    formatPrice(this.units().reduce((total, unit) => total + priceOf(unit), 0)),
  );

  constructor() {
    this.route.paramMap
      .pipe(
        map((params) => params.get('id') ?? ''),
        switchMap((id) =>
          this.screenings.load(id).pipe(
            catchError(() => {
              this.router.navigate(['/']);
              return EMPTY;
            }),
          ),
        ),
        takeUntilDestroyed(),
      )
      .subscribe((loaded) => this.view.set(loaded));
  }

  /** Takes one seat or couch out of the booking; removing the last one returns to the seat map. */
  protected remove(unit: SelectedUnit): void {
    const loaded = this.view();
    if (!loaded) {
      return;
    }
    const key = unitKey(unit.row, unit.start);
    const remaining = this.units().filter((other) => unitKey(other.row, other.start) !== key);
    this.units.set(remaining);
    this.booking.write({ screeningId: loaded.screening.id, units: remaining });
    if (remaining.length === 0) {
      this.router.navigate(['/screenings', loaded.screening.id, 'seats']);
    }
  }

  protected back(): void {
    const loaded = this.view();
    if (loaded) {
      this.router.navigate(['/screenings', loaded.screening.id, 'seats']);
    }
  }

  protected confirm(): void {
    const loaded = this.view();
    if (loaded) {
      this.router.navigate(['/screenings', loaded.screening.id, 'checkout']);
    }
  }
}

